            if (jwtIntegrationRequest.AudienceOption.IsSet)
            {
                writer.WritePropertyName("Audience");
                JsonSerializer.Serialize(writer, jwtIntegrationRequest.Audience, jsonSerializerOptions);
            }
            if (jwtIntegrationRequest.NotAfterDifferenceOption.IsSet)
                writer.WriteNumber("NotAfterDifference", jwtIntegrationRequest.NotAfterDifferenceOption.Value!.Value);

            if (jwtIntegrationRequest.NotBeforeDifferenceOption.IsSet)
                writer.WriteNumber("NotBeforeDifference", jwtIntegrationRequest.NotBeforeDifferenceOption.Value!.Value);

            if (jwtIntegrationRequest.QueryStringParameterOption.IsSet)
                writer.WriteString("QueryStringParameter", jwtIntegrationRequest.QueryStringParameter);

            var responseModeRawValue = JwtIntegrationRequest.ResponseModeEnumToJsonValue(jwtIntegrationRequest.ResponseModeOption.Value!.Value);
            writer.WriteString("ResponseMode", responseModeRawValue);
            if (jwtIntegrationRequest.LoginUrlOption.IsSet)
                writer.WriteString("LoginUrl", jwtIntegrationRequest.LoginUrl);

            if (jwtIntegrationRequest.AppNameOption.IsSet)
                writer.WriteString("AppName", jwtIntegrationRequest.AppName);
        }
    }
}
